def mask_phone(s):
    digits = sum(ch.isdigit() for ch in s)
    keep = max(0, digits - 4)
    out, seen = [], 0
    for ch in s:
        if ch.isdigit():
            out.append('*' if seen < keep else ch)
            seen += 1
        else:
            out.append(ch)
    return ''.join(out)

